namespace {

int failures = 0;

void check(bool ok, const std::string& what) {
    if (!ok) {
        ++failures;
        std::cout << "  FAIL: " << what << "\n";
    }
}

bool near(double a, double b, double tol = 0.01) { return std::fabs(a - b) <= tol; }

EngineScore scoreFrom(const json::Value& v) {
    return v.has("mate") ? EngineScore::Mate(static_cast<int>(v.at("mate").asInt()))
                         : EngineScore::Cp(static_cast<int>(v.at("cp").asInt()));
}

ReviewConfig configFrom(const json::Value& j) {
    ReviewConfig c;
    c.brilliantMaxLoss = j.at("brilliantMaxLoss").number;
    c.brilliantMinSacrifice = j.at("brilliantMinSacrifice").number;
    c.brilliantMaxWinBefore = j.at("brilliantMaxWinBefore").number;
    c.brilliantMinWinAfter = j.at("brilliantMinWinAfter").number;
    c.brilliantMateMinSacrifice = j.at("brilliantMateMinSacrifice").number;
    c.greatMaxLoss = j.at("greatMaxLoss").number;
    c.greatMinGap = j.at("greatMinGap").number;
    c.bookMaxLoss = j.at("bookMaxLoss").number;
    c.bestMaxLoss = j.at("bestMaxLoss").number;
    c.excellentMaxLoss = j.at("excellentMaxLoss").number;
    c.goodMaxLoss = j.at("goodMaxLoss").number;
    c.missOpponentLoss = j.at("missOpponentLoss").number;
    c.missMinWinBefore = j.at("missMinWinBefore").number;
    c.missMinLoss = j.at("missMinLoss").number;
    c.inaccuracyMaxLoss = j.at("inaccuracyMaxLoss").number;
    c.mistakeMaxLoss = j.at("mistakeMaxLoss").number;
    return c;
}

PlyInput inputFrom(const json::Value& j) {
    PlyInput in;
    in.played = j.at("played").asString();
    for (const json::Value& l : j.at("linesBefore").items) {
        in.linesBefore.push_back(EngineLine{l.at("move").asString(), scoreFrom(l.at("score")), {}});
    }
    const json::Value& after = j.at("afterBest");
    if (after.type != json::Value::Type::Null) {
        in.hasAfterBest = true;
        in.afterBest = scoreFrom(after.at("score"));
    }
    const json::Value& result = j.at("afterResult");
    if (result.type == json::Value::Type::String) {
        in.afterResult = result.asString() == "checkmate" ? AfterResult::Checkmate : AfterResult::Stalemate;
    }
    in.legalMoves = static_cast<int>(j.at("legalMoves").asInt());
    in.book = j.at("book").boolean;
    in.recapture = j.at("recapture").boolean;
    in.sacrificed = j.at("sacrificed").number;
    const json::Value& prev = j.at("opponentPrevLoss");
    if (prev.type == json::Value::Type::Number) {
        in.hasOpponentPrevLoss = true;
        in.opponentPrevLoss = prev.number;
    }
    return in;
}

std::string readFile(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) throw std::runtime_error("cannot open " + path);
    std::stringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

// Replies like an engine from a table of canned search results.
class FakeTransport : public UciTransport {
public:
    explicit FakeTransport(std::map<std::string, std::vector<std::string>> script) : script_(std::move(script)) {}
    std::vector<std::string> sent;

    void send(const std::string& line) override {
        sent.push_back(line);
        if (line == "uci") {
            out_.push_back("id name FakeFish 1");
            out_.push_back("uciok");
        } else if (line == "isready") {
            out_.push_back("readyok");
        } else if (line.compare(0, 13, "position fen ") == 0) {
            fen_ = line.substr(13);
        } else if (line.compare(0, 3, "go ") == 0) {
            const auto& infos = script_[fen_];
            for (const std::string& i : infos) out_.push_back(i);
            out_.push_back("info depth 1 currmove e2e4 currmovenumber 1");
            out_.push_back(infos.empty() ? "bestmove (none)" : "bestmove " + parseInfo(infos.front())->pv.front());
        }
    }
    bool readLine(std::string& line, std::chrono::milliseconds) override {
        if (out_.empty()) return false;
        line = out_.front();
        out_.pop_front();
        return true;
    }
    void close() override {}

private:
    std::map<std::string, std::vector<std::string>> script_;
    std::deque<std::string> out_;
    std::string fen_;
};

class SilentTransport : public UciTransport {
public:
    void send(const std::string&) override {}
    bool readLine(std::string&, std::chrono::milliseconds) override { return false; }
    void close() override {}
};

Game foolsMate() {
    Game g;
    for (const char* san : {"f3", "e5", "g4", "Qh4#"}) g.makeMoveSAN(san);
    return g;
}

}  // namespace

int runReviewTests(const std::string& dataDir) {
    failures = 0;
    json::Value data = json::parseFile(dataDir + "/review.json");
    const ReviewConfig config = configFrom(data.at("config"));

    // --- win percent and accuracy
    for (const json::Value& c : data.at("winPercent").items) {
        EngineScore s = scoreFrom(c.at("score"));
        check(near(winPercent(s), c.at("expect").number), "winPercent of " + s.str());
    }
    for (const json::Value& c : data.at("moveAccuracy").items) {
        check(near(moveAccuracy(c.at("loss").number), c.at("expect").number), "accuracy for loss " + std::to_string(c.at("loss").number));
    }
    check(gameAccuracy({}) == 100, "no moves: 100");
    check(near(gameAccuracy({100, 100}), 100), "perfect game");
    check(near(gameAccuracy({100, 20}), 46.6667), "arithmetic and harmonic mean");

    // --- classification
    int classified = 0;
    for (const json::Value& c : data.at("classify").items) {
        const std::string& name = c.at("name").asString();
        PlyScore r = classifyMove(inputFrom(c.at("input")), config);
        const json::Value& e = c.at("expect");
        bool ok = e.at("label").asString() == labelName(r.label) && near(r.loss, e.at("loss").number) &&
                  near(r.winBefore, e.at("winBefore").number) && near(r.winAfter, e.at("winAfter").number) &&
                  near(r.accuracy, e.at("accuracy").number);
        if (!ok) {
            std::cout << "  FAIL: " << name << " -> " << labelName(r.label) << " (loss " << r.loss << "), expected "
                      << e.at("label").asString() << "\n";
            ++failures;
        }
        ++classified;
    }
    std::cout << "classification: " << classified << " cases\n";

    // --- sacrifice
    for (const json::Value& c : data.at("sacrifice").items) {
        Board b;
        if (!Board::fromFEN(c.at("fen").asString(), b)) {
            check(false, "bad FEN in sacrifice case " + c.at("name").asString());
            continue;
        }
        std::vector<std::string> pv;
        for (const json::Value& m : c.at("pv").items) pv.push_back(m.asString());
        check(sacrificedValue(b, c.at("played").asString(), pv) == c.at("expect").number, "sacrifice: " + c.at("name").asString());
    }

    // --- a whole game
    for (const json::Value& g : data.at("game").items) {
        std::vector<std::string> labels;
        std::vector<double> acc[2];
        for (const json::Value& p : g.at("plies").items) {
            PlyScore r = classifyMove(inputFrom(p.at("input")), config);
            labels.push_back(labelName(r.label));
            acc[p.at("mover").asString() == "w" ? 0 : 1].push_back(r.accuracy);
        }
        const json::Value& e = g.at("expect");
        bool same = labels.size() == e.at("labels").items.size();
        for (size_t i = 0; same && i < labels.size(); ++i) same = labels[i] == e.at("labels").items[i].asString();
        check(same, "game labels: " + g.at("name").asString());
        check(near(gameAccuracy(acc[0]), e.at("accuracyWhite").number), "game white accuracy");
        check(near(gameAccuracy(acc[1]), e.at("accuracyBlack").number), "game black accuracy");
    }

    // --- engine-free review of a whole game from canned evaluations
    {
        Game g = foolsMate();
        std::vector<PositionEval> evals = {
            {{EngineLine{"e2e4", EngineScore::Cp(30), {}}, EngineLine{"d2d4", EngineScore::Cp(28), {}}}},
            {{EngineLine{"e7e5", EngineScore::Cp(120), {}}, EngineLine{"d7d5", EngineScore::Cp(100), {}}}},
            {{EngineLine{"e2e4", EngineScore::Cp(-100), {}}, EngineLine{"d2d4", EngineScore::Cp(-105), {}}}},
            {{EngineLine{"d8h4", EngineScore::Mate(1), {"d8h4"}}}},
            {},
        };
        GameReview r = reviewGame(g, evals);
        const MoveLabel want[] = {MoveLabel::Mistake, MoveLabel::Best, MoveLabel::Blunder, MoveLabel::Best};
        check(r.plies.size() == 4, "four plies reviewed");
        for (size_t i = 0; i < r.plies.size() && i < 4; ++i) {
            check(r.plies[i].label == want[i], "fool's mate ply " + std::to_string(i + 1) + " is " + labelName(want[i]));
        }
        check(r.plies.size() > 2 && r.plies[2].bestSan == "e4", "best move written in SAN");
        check(r.accuracyBlack > r.accuracyWhite, "Black played better");
        check(r.whiteWinChance.size() == 5 && r.whiteWinChance.back() == 0, "graph ends with Black mating");

        std::vector<PlyAnnotation> notes = reviewAnnotations(r);
        std::string pgn = toPGN(g, PgnHeaders{}, &notes);
        check(pgn.find("$4") != std::string::npos && pgn.find("[%eval") != std::string::npos, "reviewed PGN has glyphs and evals");
        check(pgn.find("Blunder. Best: e4") != std::string::npos, "reviewed PGN names the better move");
        PgnImport back = importPGN(pgn);
        check(back.error.empty() && back.game.history().size() == 4, "reviewed PGN reads back");
    }

    std::cout << "review: " << (failures == 0 ? "ok" : "FAILED") << "\n";
    return failures;
}

int runImportTests(const std::string& dataDir) {
    failures = 0;
    json::Value data = json::parseFile(dataDir + "/pgn.json");
    for (const json::Value& c : data.at("pgn_import_cases").items) {
        const std::string& name = c.at("name").asString();
        PgnImport r = importPGN(c.at("pgn").asString());
        std::vector<std::string> got;
        for (const HistoryEntry& h : r.game.history()) got.push_back(h.san);
        const auto& want = c.at("san").items;
        bool same = got.size() == want.size();
        for (size_t i = 0; same && i < got.size(); ++i) same = got[i] == want[i].asString();
        std::vector<std::string> problems;
        if (!same) problems.push_back("moves differ");
        if (r.result != c.at("result").asString()) problems.push_back("result " + r.result);
        bool wantError = c.has("error") && c.at("error").boolean;
        if (wantError != !r.error.empty()) problems.push_back("error flag, got '" + r.error + "'");
        if (c.has("headers")) {
            for (const auto& kv : c.at("headers").members) {
                if (r.headers[kv.first] != kv.second.asString()) problems.push_back("header " + kv.first);
            }
        }
        if (c.has("startFen") && r.game.initialBoard().toFEN() != c.at("startFen").asString()) problems.push_back("start FEN");
        if (problems.empty()) {
            std::cout << "ok   " << name << "\n";
        } else {
            ++failures;
            std::cout << "FAIL " << name << "\n";
            for (const auto& p : problems) std::cout << "       " << p << "\n";
        }
    }
    return failures;
}

int runOpeningTests(const std::string& dataDir) {
    failures = 0;
    OpeningBook book = OpeningBook::parse(readFile(dataDir + "/../data/openings.tsv"));
    check(book.size() > 3000, "loads thousands of openings (" + std::to_string(book.size()) + ")");

    Game g;
    for (const char* san : {"e4", "e5", "Nf3", "Nc6", "Bb5"}) g.makeMoveSAN(san);
    check(book.contains(g.board()), "Ruy Lopez position is in the book");
    const Opening* o = book.nameOf(g.board());
    check(o && o->name.find("Ruy Lopez") != std::string::npos, "Ruy Lopez is named");

    Game side;
    for (const char* san : {"a4", "h5", "Ra3", "Rh6"}) side.makeMoveSAN(san);
    check(!book.contains(side.board()), "a random sideline is not in the book");
    std::cout << "openings: " << (failures == 0 ? "ok" : "FAILED") << "\n";
    return failures;
}

int runEngineTests(const std::string& dataDir) {
    failures = 0;

    // --- parser, with lines recorded from Stockfish 19
    {
        auto i = parseInfo("info depth 10 seldepth 2 multipv 1 score mate 1 nodes 4064 nps 145142 hashfull 1 tbhits 0 time 28 pv d8h4");
        check(i && i->depth == 10 && i->multipv == 1 && i->score.mate && i->score.value == 1 && i->pv.size() == 1, "mate score");
        auto j = parseInfo("info depth 10 seldepth 15 multipv 2 score cp 374 nodes 4064 nps 1 time 28 pv h7h5 g4g5 d8g5 g1h3");
        check(j && j->multipv == 2 && !j->score.mate && j->score.value == 374 && j->pv.size() == 4, "centipawn score with variation");
        auto k = parseInfo("info depth 5 score cp -35 nodes 10 pv e7e5 g1f3");
        check(k && k->multipv == 1 && k->score.value == -35, "negative score, no multipv");
        check(!parseInfo("info depth 1 currmove e2e4 currmovenumber 1"), "currmove ignored");
        check(!parseInfo("info string NNUE evaluation using nn.nnue"), "string ignored");
        check(!parseInfo("info depth 8 multipv 1 score cp 12 lowerbound nodes 5 pv e2e4"), "bound line ignored");
        check(!parseInfo("readyok"), "other lines ignored");
        check(parseBestMove("bestmove d8h4 ponder a2a3") == std::optional<std::string>("d8h4"), "bestmove");
        check(parseBestMove("bestmove (none)") == std::optional<std::string>("(none)"), "bestmove none");
        check(!parseBestMove("info depth 1"), "not a bestmove");
    }

    // --- protocol and analyzer with a scripted engine
    {
        const std::string fen = Board().toFEN();
        auto fake = std::make_unique<FakeTransport>(std::map<std::string, std::vector<std::string>>{
            {fen,
             {"info depth 5 multipv 1 score cp 20 pv e2e4 e7e5", "info depth 5 multipv 2 score cp 15 pv d2d4 d7d5",
              "info depth 6 multipv 1 score cp 30 pv e2e4 c7c5", "info depth 6 multipv 2 score cp 18 pv d2d4 g8f6"}}});
        FakeTransport* raw = fake.get();
        UciEngine engine(std::move(fake));
        engine.start();
        check(engine.name() == "FakeFish 1", "engine name");
        auto lines = engine.analyze(fen, 6, 2);
        check(lines.size() == 2 && lines[0].move == "e2e4" && lines[0].score.value == 30 && lines[1].move == "d2d4",
              "the deepest result per line wins");
        bool sawOption = false, sawGo = false;
        for (const auto& s : raw->sent) {
            sawOption |= s == "setoption name MultiPV value 2";
            sawGo |= s == "go depth 6";
        }
        check(sawOption && sawGo, "MultiPV and go depth are sent");
    }
    {
        UciEngine silent(std::make_unique<SilentTransport>());
        bool threw = false;
        try {
            silent.start(std::chrono::milliseconds(100));
        } catch (const EngineError& e) {
            threw = std::string(e.what()).find("did not answer") != std::string::npos;
        }
        check(threw, "a silent engine times out with a clear message");
    }
    {
        Game g = foolsMate();
        std::vector<std::string> fens;
        for (const HistoryEntry& h : g.history()) fens.push_back(h.before.toFEN());
        auto fake = std::make_unique<FakeTransport>(std::map<std::string, std::vector<std::string>>{
            {fens[0], {"info depth 6 multipv 1 score cp 30 pv e2e4", "info depth 6 multipv 2 score cp 28 pv d2d4"}},
            {fens[1], {"info depth 6 multipv 1 score cp 120 pv e7e5", "info depth 6 multipv 2 score cp 100 pv d7d5"}},
            {fens[2], {"info depth 6 multipv 1 score cp -100 pv e2e4", "info depth 6 multipv 2 score cp -105 pv d2d4"}},
            {fens[3], {"info depth 6 multipv 1 score mate 1 pv d8h4", "info depth 6 multipv 2 score cp 374 pv h7h5"}}});
        FakeTransport* raw = fake.get();
        UciEngine engine(std::move(fake));
        engine.start();
        EngineAnalyzer analyzer(engine, 6, 2);
        std::vector<int> progress;
        GameReview r = analyzer.review(g, nullptr, ReviewConfig{}, [&](int done, int) { progress.push_back(done); });
        const MoveLabel want[] = {MoveLabel::Mistake, MoveLabel::Best, MoveLabel::Blunder, MoveLabel::Best};
        for (size_t i = 0; i < 4 && i < r.plies.size(); ++i) check(r.plies[i].label == want[i], "analyzer ply " + std::to_string(i + 1));
        check(progress == std::vector<int>({1, 2, 3, 4, 5}), "progress is reported");
        auto goCount = [&] {
            int n = 0;
            for (const auto& s : raw->sent) n += s.compare(0, 3, "go ") == 0;
            return n;
        };
        check(goCount() == 4, "the finished position is not searched");
        analyzer.review(g);
        check(goCount() == 4, "the second review comes from the cache");

        std::atomic<bool> cancel{true};
        bool cancelled = false;
        try {
            EngineAnalyzer(engine).review(g, nullptr, ReviewConfig{}, {}, &cancel);
        } catch (const ReviewCancelled&) {
            cancelled = true;
        }
        check(cancelled, "a review can be cancelled");
    }

    // --- real Stockfish, when installed (tools/get_stockfish.ps1)
    std::string path = findEnginePath();
    if (path.empty()) {
        std::cout << "real Stockfish: skipped (not installed)\n";
    } else {
        auto transport = openProcessTransport(path);
        check(transport != nullptr, "Stockfish starts");
        if (transport) {
            UciEngine engine(std::move(transport));
            engine.start();
            check(engine.name().rfind("Stockfish", 0) == 0, "engine name is Stockfish: " + engine.name());
            auto mate = engine.analyze("6k1/5ppp/8/8/8/8/5PPP/R5K1 w - - 0 1", 8, 1);
            check(!mate.empty() && mate[0].move == "a1a8" && mate[0].score.mate && mate[0].score.value == 1, "finds mate in one");

            OpeningBook book = OpeningBook::parse(readFile(dataDir + "/../data/openings.tsv"));
            json::Value data = json::parseFile(dataDir + "/review.json");
            for (const json::Value& g : data.at("engineGames").items) {
                Game game;
                for (const json::Value& s : g.at("san").items) game.makeMoveSAN(s.asString());
                EngineAnalyzer analyzer(engine);
                analyzer.configure();
                GameReview r = analyzer.review(game, &book);
                for (const json::Value& e : g.at("expect").items) {
                    const PlyReview& p = r.plies[static_cast<size_t>(e.at("ply").asInt()) - 1];
                    bool ok = false;
                    for (const json::Value& one : e.at("oneOf").items) ok |= one.asString() == labelName(p.label);
                    check(ok, g.at("name").asString() + ": ply " + std::to_string(p.ply) + " " + p.san + " was " + labelName(p.label));
                }
                std::cout << "real Stockfish reviewed " << g.at("name").asString() << ": white " << r.accuracyWhite
                          << "%, black " << r.accuracyBlack << "%\n";
            }
        }
    }

    std::cout << "engine: " << (failures == 0 ? "ok" : "FAILED") << "\n";
    return failures;
}
